def covers(vp, vlen, p, plen):  # VRP 대역이 광고 대역 포함?
    if plen < vlen:
        return False
    shift = 32 - vlen
    return (vp >> shift) == (p >> shift)

def rov(prefix, plen, origin_as, vrps):
    # vrps: ROA 검증 결과 (프리픽스, 길이, 최대 길이, AS)
    covered = False
    for vp, vlen, maxlen, asn in vrps:
        if covers(vp, vlen, prefix, plen):
            covered = True  # 해당 대역에 ROA 존재
            if origin_as == asn and plen <= maxlen:
                return 'Valid'
    return 'Invalid' if covered else 'NotFound'
